const allItems = $input.all().map(i => i.json);

const totalPatients = allItems.filter(i => i.source === 'patients').length;
const totalAppointments = allItems.filter(i => i.source === 'appointments').length;
const cancelledAppointments = allItems.filter(i => i.source === 'appointments' && i.status === 'Cancelled').length;
const riskAlerts = allItems.filter(i => i.source === 'risk_alerts').length;

return [{
  json: {
    report_date: new Date().toISOString().split('T')[0],
    total_patients: totalPatients,
    total_appointments: totalAppointments,
    cancelled_appointments: cancelledAppointments,
    high_risk_patients: riskAlerts,
    summary: `Daily Report: ${totalPatients} patients, ${totalAppointments} appointments, ${cancelledAppointments} cancelled, ${riskAlerts} high-risk patients flagged.`
  }
}];

const appointments = $input.all().map(item => item.json);

// Group by patient_name
const patientMap = {};
for (const appt of appointments) {
  const name = appt.patient_name;
  if (!patientMap[name]) {
    patientMap[name] = { total: 0, cancelled: 0 };
  }
  patientMap[name].total++;
  if (appt.status === 'Cancelled') {
    patientMap[name].cancelled++;
  }
}

// Calculate risk for each patient
const results = [];
for (const name in patientMap) {
  const data = patientMap[name];
  const cancelRate = data.cancelled / data.total;
  let risk = 'LOW';
  if (cancelRate >= 0.5) risk = 'HIGH';
  else if (cancelRate >= 0.25) risk = 'MEDIUM';

  results.push({
    json: {
      patient_name: name,
      total_appointments: data.total,
      cancelled_count: data.cancelled,
      cancel_rate: cancelRate,
      risk_level: risk
    }
  });
}

return results;

const appointments = $input.all().map(item => item.json);
const today = new Date().toISOString().split('T')[0];

const upcoming = appointments.filter(appt => {
  return appt.appointment_date === today && appt.status === 'Booked';
});

return upcoming.map(appt => ({ json: appt }));
